import json
import ast

# Simulate loading data
data = [{'status': 'delivered', 'details': "{'channel': 'web', 'shipping': {'method': 'standard', 'cost': 6.49, 'address': {'city': 'Lyon', 'country': 'FR', 'postal_code': 12345}}, 'notes': None}"}]
