def get_city(details):
    try:
        # The provided code's parsing:
        if isinstance(details, str):
            details_dict = json.loads(details.replace("'", '"')) 
        else:
            details_dict = details
        return details_dict.get('shipping', {}).get('address', {}).get('city')
    except Exception as e:
        return f"Error: {e}"

print(get_city(df['details'][0]))
